package main

import (
	"fmt"
	"os"
	"strconv"
)

func midpoint(lo, hi int64) int64 { return (lo + hi) / 2 }

func main() {
	if len(os.Args) != 3 {
		fmt.Println("error")
		os.Exit(2)
	}
	lo, first := strconv.ParseInt(os.Args[1], 10, 64)
	hi, second := strconv.ParseInt(os.Args[2], 10, 64)
	if first != nil || second != nil || lo > hi {
		fmt.Println("error")
		os.Exit(2)
	}
	fmt.Println(midpoint(lo, hi))
}

