import (
	"fmt"
	"os"
	"strings"
)

func encode(text string) string {
	parts := []string{}
	var previous rune
	count := 0
	for i := 0; i < len(text); i++ {
		current := rune(text[i])
		if count > 0 && previous != current {
			parts = append(parts, fmt.Sprintf("%04X:%d", previous, count))
			count = 0
		}
		previous = current
		count++
	}
	if count > 0 {
		parts = append(parts, fmt.Sprintf("%04X:%d", previous, count))
	}
	return strings.Join(parts, ",")
}

func main() {
	if len(os.Args) != 2 {
		fmt.Println("error")
		os.Exit(2)
	}
	fmt.Println(encode(os.Args[1]))
